<?php
namespace App\Services;use Illuminate\Support\Facades\Http;use RuntimeException;
class MidtransService{private string $snapBase;private string $apiBase;private string $serverKey;public function __construct(){$this->snapBase=config('services.midtrans.snap_url');$this->apiBase=config('services.midtrans.api_url');$this->serverKey=(string)config('services.midtrans.server_key');}public function createSnapTransaction(array $p):array{$r=Http::withBasicAuth($this->serverKey,'')->acceptJson()->timeout(15)->post($this->snapBase.'/v1/transactions',$p);if($r->failed())throw new RuntimeException('Midtrans transaction creation failed: '.$r->body());return $r->json();}public function getStatus(string $id):array{$r=Http::withBasicAuth($this->serverKey,'')->acceptJson()->timeout(10)->get($this->apiBase.'/v2/'.rawurlencode($id).'/status');if($r->status()===404)return[];if($r->failed())throw new RuntimeException('Midtrans status verification failed: '.$r->body());return$r->json();}public function verifySignature(array $n):bool{$sig=$n['signature_key']??'';$raw=($n['order_id']??'').($n['status_code']??'').($n['gross_amount']??'').$this->serverKey;return$sig!==''&&hash_equals($sig,hash('sha512',$raw));}public function isSuccessful(array $s):bool{$t=strtolower((string)($s['transaction_status']??''));$f=strtolower((string)($s['fraud_status']??''));return in_array($t,['settlement','capture'],true)&&($f===''||$f==='accept');}}
